export const KERNEL_ROOTKIT_TECHNIQUES = [
  {
    name: "Syscall Table Hooking",
    desc: "Overwrite entries in the sys_call_table to redirect syscalls to attacker-controlled functions. The hook function can filter results (e.g., hide files from getdents, hide processes from /proc reads, hide network connections).",
    detection: "Compare sys_call_table entries against System.map or /proc/kallsyms. Look for pointers outside the kernel text range. Check if sys_call_table page is writable (should be read-only).",
  },
  {
    name: "VFS/File Operations Hooking",
    desc: "Replace function pointers in file_operations or inode_operations structs for specific filesystems (e.g., /proc). This is more targeted than syscall hooking — only affects operations on specific filesystem paths.",
    detection: "Compare file_operations function pointers against known-good values. Check if kernel data pages have unexpected write permissions.",
  },
  {
    name: "Inline Function Hooking (ftrace abuse)",
    desc: "Patch the first bytes of a kernel function with a jump to the rootkit's handler. Can use ftrace infrastructure for a more stable hook. The handler can modify arguments, return values, or skip the original function entirely.",
    detection: "Check function prologues for unexpected JMP/CALL instructions. Verify ftrace callback registrations. Compare kernel text with known-good image.",
  },
  {
    name: "Direct Kernel Object Manipulation (DKOM)",
    desc: "Modify kernel data structures directly without hooking any code. For example, unlink a task_struct from the task list to hide a process, remove a module from the module list to hide the rootkit LKM, or modify network data structures to hide connections.",
    detection: "Cross-reference process lists from multiple sources (/proc, task list walk, scheduler run queues). Count scheduler entities vs. visible processes. Check for orphaned memory regions.",
  },
  {
    name: "eBPF-Based Rootkit",
    desc: "Use eBPF programs to hook into kernel functions (via kprobes) and modify their behavior. The eBPF program can filter data returned to userspace (hide files, processes, connections) without modifying kernel memory or loading a kernel module. Hard to detect because eBPF is a legitimate kernel facility.",
    detection: "List loaded BPF programs: bpftool prog list. Check kprobe attachments: cat /sys/kernel/debug/kprobes/list. Look for unexpected BPF programs attached to security-relevant functions.",
  },
  {
    name: "Kernel Module Hiding",
    desc: "After loading, the rootkit module removes itself from the module list (list_del from modules list), making it invisible to lsmod and /proc/modules. The module code remains in memory and functional.",
    detection: "Compare total kernel memory usage with accounted module memory. Scan kernel memory for module signatures. Check /sys/module/ (may still have entries even if /proc/modules is hidden).",
  },
];

